export const GUIDED: Record<string, GuidedLab> = {"labex-go-implementing-go-timeouts-with-channels":{"intro":"The purpose of this lab is to implement timeouts in Go using channels and select.","steps":[{"title":"Timeouts","body":["When programs connect to external resources or need to bound execution time, timeouts are important. The lab is to implement timeouts in Go using channels and select.","• Implement timeouts in Go using channels and select. • Use a buffered channel to prevent goroutine leaks in case the channel is never read. • Use time.After to await a value to be sent after the timeout. • Use select to proceed with the first receive that's ready."],"code":[{"lang":"sh","text":"# Running this program shows the first operation timing\n# out and the second succeeding.\n$ go run timeouts.go\ntimeout 1\nresult 2"},{"lang":"go","text":"// _Timeouts_ are important for programs that connect to\n// external resources or that otherwise need to bound\n// execution time. Implementing timeouts in Go is easy and\n// elegant thanks to channels and `select`.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// For our example, suppose we're executing an external\n\t// call that returns its result on a channel `c1`\n\t// after 2s. Note that the channel is buffered, so the\n\t// send in the goroutine is nonblocking. This is a\n\t// common pattern to prevent goroutine leaks in case the\n\t// channel is never read.\n\tc1 := make(chan string, 1)\n\tgo func() {\n\t\ttime.Sleep(2 * time.Second)\n\t\tc1 <- \"result 1\"\n\t}()\n\n\t// Here's the `select` implementing a timeout.\n\t// `res := <-c1` awaits the result and `<-time.After`\n\t// awaits a value to be sent after the timeout of\n\t// 1s. Since `select` proceeds with the first\n\t// receive that's ready, we'll take the timeout case\n\t// if the operation takes more than the allowed 1s.\n\tselect {\n\tcase res := <-c1:\n\t\tfmt.Println(res)\n\tcase <-time.After(1 * time.Second):\n\t\tfmt.Println(\"timeout 1\")\n\t}\n\n\t// If we allow a longer timeout of 3s, then the receive\n\t// from `c2` will succeed and we'll print the result.\n\tc2 := make(chan string, 1)\n\tgo func() {\n\t\ttime.Sleep(2 * time.Second)\n\t\tc2 <- \"result 2\"\n\t}()\n\tselect {\n\tcase res := <-c2:"}]}],"commands":["go run timeouts.go"],"reference":[{"path":"timeouts.go","text":"// _Timeouts_ are important for programs that connect to\n// external resources or that otherwise need to bound\n// execution time. Implementing timeouts in Go is easy and\n// elegant thanks to channels and `select`.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// For our example, suppose we're executing an external\n\t// call that returns its result on a channel `c1`\n\t// after 2s. Note that the channel is buffered, so the\n\t// send in the goroutine is nonblocking. This is a\n\t// common pattern to prevent goroutine leaks in case the\n\t// channel is never read.\n\t// Here's the `select` implementing a timeout.\n\t// `res := <-c1` awaits the result and `<-time.After`\n\t// awaits a value to be sent after the timeout of\n\t// 1s. Since `select` proceeds with the first\n\t// receive that's ready, we'll take the timeout case\n\t// if the operation takes more than the allowed 1s.\n\t// If we allow a longer timeout of 3s, then the receive\n\t// from `c2` will succeed and we'll print the result.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-timer-and-ticker-tutorial":{"intro":"This lab focuses on the use of timers and tickers in Golang. Timers and tickers are useful for executing code at a specific time or repeatedly at a given interval.","steps":[{"title":"Timers","body":["The lab requires the implementation of a timer that waits for a specified duration and then fires. Additionally, the timer should be cancellable before it fires.","• The time package should be imported. • Two timers should be created, one that waits for 2 seconds and another that waits for 1 second. • The first timer should print \"Timer 1 fired\" when it fires. • The second timer should print \"Timer 2 fired\" when it fires. • The second timer should be cancelled before it fires. • The program should wait for 2 seconds to show that the second timer did not fire."],"code":[{"lang":"sh","text":"// The first timer will fire ~2s after we start the\n// program, but the second should be stopped before it has\n// a chance to fire.\n$ go run timers.go\nTimer 1 fired\nTimer 2 stopped"},{"lang":"go","text":"// We often want to execute Go code at some point in the\n// future, or repeatedly at some interval. Go's built-in\n// _timer_ and _ticker_ features make both of these tasks\n// easy. We'll look first at timers and then\n// at [tickers](tickers).\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// Timers represent a single event in the future. You\n\t// tell the timer how long you want to wait, and it\n\t// provides a channel that will be notified at that\n\t// time. This timer will wait 2 seconds.\n\ttimer1 := time.NewTimer(2 * time.Second)\n\n\t// The `<-timer1.C` blocks on the timer's channel `C`\n\t// until it sends a value indicating that the timer\n\t// fired.\n\t<-timer1.C\n\tfmt.Println(\"Timer 1 fired\")\n\n\t// If you just wanted to wait, you could have used\n\t// `time.Sleep`. One reason a timer may be useful is\n\t// that you can cancel the timer before it fires.\n\t// Here's an example of that.\n\ttimer2 := time.NewTimer(time.Second)\n\tgo func() {\n\t\t<-timer2.C\n\t\tfmt.Println(\"Timer 2 fired\")\n\t}()\n\tstop2 := timer2.Stop()\n\tif stop2 {\n\t\tfmt.Println(\"Timer 2 stopped\")\n\t}\n\n\t// Give the `timer2` enough time to fire, if it ever\n\t// was going to, to show it is in fact stopped.\n\ttime.Sleep(2 * time.Second)\n}"}]}],"commands":["go run timers.go"],"reference":[{"path":"timers.go","text":"// We often want to execute Go code at some point in the\n// future, or repeatedly at some interval. Go's built-in\n// _timer_ and _ticker_ features make both of these tasks\n// easy. We'll look first at timers and then\n// at [tickers](tickers).\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// Timers represent a single event in the future. You\n\t// tell the timer how long you want to wait, and it\n\t// provides a channel that will be notified at that\n\t// time. This timer will wait 2 seconds.\n\t// The `<-timer1.C` blocks on the timer's channel `C`\n\t// until it sends a value indicating that the timer\n\t// fired.\n\t// If you just wanted to wait, you could have used\n\t// `time.Sleep`. One reason a timer may be useful is\n\t// that you can cancel the timer before it fires.\n\t// Here's an example of that.\n\t// Give the `timer2` enough time to fire, if it ever\n\t// was going to, to show it is in fact stopped.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-basics-value-types-exploration":{"intro":"This lab aims to test your understanding of Golang's basic value types, including strings, integers, floats, and booleans.","steps":[{"title":"Value Types","body":["Your task is to complete the calculate function that takes in two integers and returns their sum and product.","• The calculate function should take in two integers as parameters. • The calculate function should return two integers, the sum and product of the input parameters."],"code":[{"lang":"sh","text":"$ go run values.go\ngolang\n1+1 = 2\n7.0/3.0 = 2.3333333333333335\nfalse\ntrue\nfalse"},{"lang":"go","text":"// Go has various value types including strings,\n// integers, floats, booleans, etc. Here are a few\n// basic examples.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Strings, which can be added together with `+`.\n\tfmt.Println(\"go\" + \"lang\")\n\n\t// Integers and floats.\n\tfmt.Println(\"1+1 =\", 1+1)\n\tfmt.Println(\"7.0/3.0 =\", 7.0/3.0)\n\n\t// Booleans, with boolean operators as you'd expect.\n\tfmt.Println(true && false)\n\tfmt.Println(true || false)\n\tfmt.Println(!true)\n}"}]}],"commands":["go run values.go"],"reference":[{"path":"values.go","text":"// Go has various value types including strings,\n// integers, floats, booleans, etc. Here are a few\n// basic examples.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Strings, which can be added together with `+`.\n\t// Integers and floats.\n\t// Booleans, with boolean operators as you'd expect.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-exploring-golang-variable-declarations":{"intro":"This lab aims to test your understanding of variables in Golang. In Golang, variables are explicitly declared and used by the compiler to check the type-correctness of function calls.","steps":[{"title":"Variables","body":["You are required to complete the code to declare and initialize variables of different types in Golang.","• Basic knowledge of Golang syntax • Familiarity with variable declaration and initialization in Golang"],"code":[{"lang":"sh","text":"$ go run variables.go\ninitial\n1 2\ntrue\n0\napple"},{"lang":"go","text":"// In Go, _variables_ are explicitly declared and used by\n// the compiler to e.g. check type-correctness of function\n// calls.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// `var` declares 1 or more variables.\n\tvar a = \"initial\"\n\tfmt.Println(a)\n\n\t// You can declare multiple variables at once.\n\tvar b, c int = 1, 2\n\tfmt.Println(b, c)\n\n\t// Go will infer the type of initialized variables.\n\tvar d = true\n\tfmt.Println(d)\n\n\t// Variables declared without a corresponding\n\t// initialization are _zero-valued_. For example, the\n\t// zero value for an `int` is `0`.\n\tvar e int\n\tfmt.Println(e)\n\n\t// The `:=` syntax is shorthand for declaring and\n\t// initializing a variable, e.g. for\n\t// `var f string = \"apple\"` in this case.\n\t// This syntax is only available inside functions.\n\tf := \"apple\"\n\tfmt.Println(f)\n}"}]}],"commands":["go run variables.go"],"reference":[{"path":"variables.go","text":"// In Go, _variables_ are explicitly declared and used by\n// the compiler to e.g. check type-correctness of function\n// calls.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// `var` declares 1 or more variables.\n\t// You can declare multiple variables at once.\n\t// Go will infer the type of initialized variables.\n\t// Variables declared without a corresponding\n\t// initialization are _zero-valued_. For example, the\n\t// zero value for an `int` is `0`.\n\t// The `:=` syntax is shorthand for declaring and\n\t// initializing a variable, e.g. for\n\t// `var f string = \"apple\"` in this case.\n\t// This syntax is only available inside functions.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-waitgroups-coordinating-concurrent-goroutine":{"intro":"The waitgroups lab is designed to help you understand how to use a wait group to wait for multiple goroutines to finish.","steps":[{"title":"WaitGroups","body":["The problem to be solved in this lab is to launch several goroutines and increment the WaitGroup counter for each. Then, we need to wait for all the goroutines launched to finish.","• Basic knowledge of Golang. • Understanding of concurrency in Golang. • Familiarity with the sync package."],"code":[{"lang":"sh","text":"$ go run waitgroups.go\nWorker 5 starting\nWorker 3 starting\nWorker 4 starting\nWorker 1 starting\nWorker 2 starting\nWorker 4 done\nWorker 1 done\nWorker 2 done\nWorker 5 done\nWorker 3 done\n\n# The order of workers starting up and finishing\n# is likely to be different for each invocation."},{"lang":"go","text":"// To wait for multiple goroutines to finish, we can\n// use a *wait group*.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n\t\"time\"\n)\n\n// This is the function we'll run in every goroutine.\nfunc worker(id int) {\n\tfmt.Printf(\"Worker %d starting\\n\", id)\n\n\t// Sleep to simulate an expensive task.\n\ttime.Sleep(time.Second)\n\tfmt.Printf(\"Worker %d done\\n\", id)\n}\n\nfunc main() {\n\n\t// This WaitGroup is used to wait for all the\n\t// goroutines launched here to finish. Note: if a WaitGroup is\n\t// explicitly passed into functions, it should be done *by pointer*.\n\tvar wg sync.WaitGroup\n\n\t// Launch several goroutines and increment the WaitGroup\n\t// counter for each.\n\tfor i := 1; i <= 5; i++ {\n\t\twg.Add(1)\n\t\t// Avoid re-use of the same `i` value in each goroutine closure.\n\t\t// See [the FAQ](https://golang.org/doc/faq#closures_and_goroutines)\n\t\t// for more details.\n\t\ti := i\n\n\t\t// Wrap the worker call in a closure that makes sure to tell\n\t\t// the WaitGroup that this worker is done. This way the worker\n\t\t// itself does not have to be aware of the concurrency primitives\n\t\t// involved in its execution.\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tworker(i)\n\t\t}()\n\t}\n\n\t// Block until the WaitGroup counter goes back to 0;\n\t// all the workers notified they're done."}]}],"commands":["go run waitgroups.go"],"reference":[{"path":"waitgroups.go","text":"// To wait for multiple goroutines to finish, we can\n// use a *wait group*.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n\t\"time\"\n)\n\n// This is the function we'll run in every goroutine.\nfunc main() {\n    // TODO\n\t// Sleep to simulate an expensive task.\n\t// This WaitGroup is used to wait for all the\n\t// goroutines launched here to finish. Note: if a WaitGroup is\n\t// explicitly passed into functions, it should be done *by pointer*.\n\t// Launch several goroutines and increment the WaitGroup\n\t// counter for each.\n\t// Avoid re-use of the same `i` value in each goroutine closure.\n\t// See [the FAQ](https://golang.org/doc/faq#closures_and_goroutines)\n\t// for more details.\n\t// Wrap the worker call in a closure that makes sure to tell\n\t// the WaitGroup that this worker is done. This way the worker\n\t// itself does not have to be aware of the concurrency primitives\n\t// involved in its execution.\n\t// Block until the WaitGroup counter goes back to 0;\n\t// all the workers notified they're done.\n\t// Note that this approach has no straightforward way\n\t// to propagate errors from workers. For more\n\t// advanced use cases, consider using the\n\t// [errgroup package](https://pkg.go.dev/golang.org/x/sync/errgroup).\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-worker-pool-with-goroutines-and-channels":{"intro":"This lab demonstrates how to implement a worker pool using goroutines and channels.","steps":[{"title":"Worker Pools","body":["Implement a worker pool that receives work on the jobs channel and sends the corresponding results on the results channel. The worker pool should have multiple concurrent instances, and each worker should sleep for a second per job to simulate an expensive task.","• Use goroutines and channels to implement the worker pool. • The worker pool should have multiple concurrent instances. • Each worker should sleep for a second per job to simulate an expensive task. • The worker pool should receive work on the jobs channel and send the corresponding results on the results channel."],"code":[{"lang":"sh","text":"# Our running program shows the 5 jobs being executed by\n# various workers. The program only takes about 2 seconds\n# despite doing about 5 seconds of total work because\n# there are 3 workers operating concurrently.\n$ time go run worker-pools.go\nworker 1 started job 1\nworker 2 started job 2\nworker 3 started job 3\nworker 1 finished job 1\nworker 1 started job 4\nworker 2 finished job 2\nworker 2 started job 5\nworker 3 finished job 3\nworker 1 finished job 4\nworker 2 finished job 5\n\nreal 0m2.358s"},{"lang":"go","text":"// In this example we'll look at how to implement\n// a _worker pool_ using goroutines and channels.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\n// Here's the worker, of which we'll run several\n// concurrent instances. These workers will receive\n// work on the `jobs` channel and send the corresponding\n// results on `results`. We'll sleep a second per job to\n// simulate an expensive task.\nfunc worker(id int, jobs <-chan int, results chan<- int) {\n\tfor j := range jobs {\n\t\tfmt.Println(\"worker\", id, \"started  job\", j)\n\t\ttime.Sleep(time.Second)\n\t\tfmt.Println(\"worker\", id, \"finished job\", j)\n\t\tresults <- j * 2\n\t}\n}\n\nfunc main() {\n\n\t// In order to use our pool of workers we need to send\n\t// them work and collect their results. We make 2\n\t// channels for this.\n\tconst numJobs = 5\n\tjobs := make(chan int, numJobs)\n\tresults := make(chan int, numJobs)\n\n\t// This starts up 3 workers, initially blocked\n\t// because there are no jobs yet.\n\tfor w := 1; w <= 3; w++ {\n\t\tgo worker(w, jobs, results)\n\t}\n\n\t// Here we send 5 `jobs` and then `close` that\n\t// channel to indicate that's all the work we have.\n\tfor j := 1; j <= numJobs; j++ {\n\t\tjobs <- j\n\t}\n\tclose(jobs)\n\n\t// Finally we collect all the results of the work.\n\t// This also ensures that the worker goroutines have"}]}],"commands":[],"reference":[{"path":"worker-pools.go","text":"// In this example we'll look at how to implement\n// a _worker pool_ using goroutines and channels.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\n// Here's the worker, of which we'll run several\n// concurrent instances. These workers will receive\n// work on the `jobs` channel and send the corresponding\n// results on `results`. We'll sleep a second per job to\n// simulate an expensive task.\nfunc main() {\n    // TODO\n\t// In order to use our pool of workers we need to send\n\t// them work and collect their results. We make 2\n\t// channels for this.\n\t// This starts up 3 workers, initially blocked\n\t// because there are no jobs yet.\n\t// Here we send 5 `jobs` and then `close` that\n\t// channel to indicate that's all the work we have.\n\t// Finally we collect all the results of the work.\n\t// This also ensures that the worker goroutines have\n\t// finished. An alternative way to wait for multiple\n\t// goroutines is to use a [WaitGroup](waitgroups).\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-xml-mapping-and-manipulation":{"intro":"This lab aims to test your knowledge of working with XML in Golang. You will be required to create a struct that can be mapped to XML, marshal and unmarshal XML data, and use field tags to define the structure of the XML output.","steps":[{"title":"XML","body":["You are required to create a struct named Plant that can be mapped to XML. The struct should have the following fields:","• Id (int) - an XML attribute • Name (string) - a nested XML element • Origin ([]string) - a nested XML element","You should also create a struct named Nesting that contains a slice of Plant structs. The Nesting struct should be mapped to an XML element named nesting, and the Plant structs should be nested under <parent><child>....","You should then write code to marshal the Plant and Nesting structs to XML, and unmarshal XML data into the Plant struct."],"code":[{"lang":"sh","text":"$ go run xml.go\n <plant id=\"27\">\n   <name>Coffee</name>\n   <origin>Ethiopia</origin>\n   <origin>Brazil</origin>\n </plant>\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n <plant id=\"27\">\n   <name>Coffee</name>\n   <origin>Ethiopia</origin>\n   <origin>Brazil</origin>\n </plant>\nPlant id=27, name=Coffee, origin=[Ethiopia Brazil]\n <nesting>\n   <parent>\n     <child>\n       <plant id=\"27\">\n         <name>Coffee</name>\n         <origin>Ethiopia</origin>\n         <origin>Brazil</origin>\n       </plant>\n       <plant id=\"81\">\n         <name>Tomato</name>\n         <origin>Mexico</origin>\n         <origin>California</origin>\n       </plant>\n     </child>\n   </parent>\n </nesting>"},{"lang":"go","text":"// Go offers built-in support for XML and XML-like\n// formats with the `encoding.xml` package.\n\npackage main\n\nimport (\n\t\"encoding/xml\"\n\t\"fmt\"\n)\n\n// Plant will be mapped to XML. Similarly to the\n// JSON examples, field tags contain directives for the\n// encoder and decoder. Here we use some special features\n// of the XML package: the `XMLName` field name dictates\n// the name of the XML element representing this struct;\n// `id,attr` means that the `Id` field is an XML\n// _attribute_ rather than a nested element.\ntype Plant struct {\n\tXMLName xml.Name `xml:\"plant\"`\n\tId      int      `xml:\"id,attr\"`\n\tName    string   `xml:\"name\"`\n\tOrigin  []string `xml:\"origin\"`\n}\n\nfunc (p Plant) String() string {\n\treturn fmt.Sprintf(\"Plant id=%v, name=%v, origin=%v\",\n\t\tp.Id, p.Name, p.Origin)\n}\n\nfunc main() {\n\tcoffee := &Plant{Id: 27, Name: \"Coffee\"}\n\tcoffee.Origin = []string{\"Ethiopia\", \"Brazil\"}\n\n\t// Emit XML representing our plant; using\n\t// `MarshalIndent` to produce a more\n\t// human-readable output.\n\tout, _ := xml.MarshalIndent(coffee, \" \", \"  \")\n\tfmt.Println(string(out))\n\n\t// To add a generic XML header to the output, append\n\t// it explicitly.\n\tfmt.Println(xml.Header + string(out))\n\n\t// Use `Unmarshal` to parse a stream of bytes with XML\n\t// into a data structure. If the XML is malformed or\n\t// cannot be mapped onto Plant, a descriptive error\n\t// will be returned.\n\tvar p Plant"}]}],"commands":["go run xml.go"],"reference":[{"path":"xml.go","text":"// Go offers built-in support for XML and XML-like\n// formats with the `encoding.xml` package.\n\npackage main\n\nimport (\n\t\"encoding/xml\"\n\t\"fmt\"\n)\n\n// Plant will be mapped to XML. Similarly to the\n// JSON examples, field tags contain directives for the\n// encoder and decoder. Here we use some special features\n// of the XML package: the `XMLName` field name dictates\n// the name of the XML element representing this struct;\n// `id,attr` means that the `Id` field is an XML\n// _attribute_ rather than a nested element.\ntype Plant struct {\n\tXMLName xml.Name `xml:\"plant\"`\n\tId      int      `xml:\"id,attr\"`\n\tName    string   `xml:\"name\"`\n\tOrigin  []string `xml:\"origin\"`\n}\n\nfunc main() {\n    // TODO\n\t// Emit XML representing our plant; using\n\t// `MarshalIndent` to produce a more\n\t// human-readable output.\n\t// To add a generic XML header to the output, append\n\t// it explicitly.\n\t// Use `Unmarshal` to parse a stream of bytes with XML\n\t// into a data structure. If the XML is malformed or\n\t// cannot be mapped onto Plant, a descriptive error\n\t// will be returned.\n\t// The `parent>child>plant` field tag tells the encoder\n\t// to nest all `plant`s under `<parent><child>...`\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"}};
